// Expected bytes are generated by the independent iGate Python client, not
// the Go simulator. Normal Go tests only read this frozen JSON fixture.
func TestReferenceClientWireVectors(t *testing.T) {
	var f struct {
		Key                   string `json:"key"`
		RouteKey              string `json:"route_key"`
		Source, Target, Relay string
		ImageHex              string `json:"image_hex"`
		Frames                []struct {
			Name                         string
			Op                           byte
			Offset                       uint32
			Nonce, Payload, Wire, Routed string
		}
		Replies []struct {
			Name, Wire, Routed string
			Expected           struct {
				Nonce           string
				Op, Status      byte
				Offset, Written uint32
				Bitmap          uint32
				Version         string
				ImageSHA        string `json:"image_sha"`
				Running, Boot   uint32
				Pending         *bool
				WiFiMode        byte `json:"wifi_mode"`
				Connected       bool
				ActiveInterface bool `json:"active_interface"`
			}
		}
	}
	raw, err := os.ReadFile("testdata/reference-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(raw, &f); err != nil {
		t.Fatal(err)
	}
	decode := func(s string) []byte {
		b, err := hex.DecodeString(s)
		if err != nil {
			t.Fatal(err)
		}
		return b
	}
	key, routeKey := decode(f.Key), decode(f.RouteKey)
	for _, v := range f.Frames {
		t.Run(v.Name, func(t *testing.T) {
			var nonce [8]byte
			copy(nonce[:], decode(v.Nonce))
			got, err := frame(key, f.Source, f.Target, nonce, v.Op, v.Offset, decode(v.Payload))
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, decode(v.Wire)) {
				t.Fatalf("wire mismatch\ngot  %x\nwant %s", got, v.Wire)
			}
			routed, err := wrapRoute(routeKey, f.Source, got)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(routed, decode(v.Routed)) {
				t.Fatal("route bytes differ from reference")
			}
			if v.Op == 15 {
				image := decode(f.ImageHex)
				sum := sha256.Sum256(image)
				p := decode(v.Payload)
				if binary.BigEndian.Uint32(p[:4]) != uint32(len(image)) || !bytes.Equal(p[4:36], sum[:]) {
					t.Fatal("reference manifest mismatch")
				}
			}
		})
	}
	for _, v := range f.Replies {
		t.Run(v.Name, func(t *testing.T) {
			inner, err := unwrapRoute(routeKey, f.Relay, decode(v.Routed))
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(inner, decode(v.Wire)) {
				t.Fatal("route payload changed")
			}
			r, err := decodeReply(key, f.Source, f.Target, inner)
			if err != nil {
				t.Fatal(err)
			}
			want := v.Expected
			if r.Op != want.Op || r.Status != want.Status || r.Offset != want.Offset || r.Written != want.Written || hex.EncodeToString(r.Nonce[:]) != want.Nonce {
				t.Fatal(r, want)
			}
			if want.Pending != nil {
				if r.Proof == nil || *r.Proof.Pending != *want.Pending || r.Proof.Version != want.Version || r.Proof.ImageSHA != want.ImageSHA || r.Proof.Running != want.Running || r.Proof.Boot != want.Boot {
					t.Fatal(r, want)
				}
			}
			if r.HasBitmap && r.Bitmap != want.Bitmap {
				t.Fatal("bitmap differs")
			}
			if r.HasNetwork && (r.WiFiMode != want.WiFiMode || r.Connected != want.Connected || r.ActiveInterface != want.ActiveInterface) {
				t.Fatal("network state differs")
			}
		})
	}
}

// Compare the actual profile/manifest/block/query frames emitted by the engine,
// not just its generic frame encoder, with the reference client's frozen bytes.
func TestNativeTransferEmissionsMatchReference(t *testing.T) {
	var f struct {
		Nonce    string
		ImageHex string `json:"image_hex"`
		RouteKey string `json:"route_key"`
		Frames   []struct {
			Name         string
			Op           byte
			Offset       uint32
			Wire, Routed string
		}
	}
	b, err := os.ReadFile("testdata/reference-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	image, err := hex.DecodeString(f.ImageHex)
	if err != nil {
		t.Fatal(err)
	}
	nonceBytes, _ := hex.DecodeString(f.Nonce)
	var nonce [8]byte
	copy(nonce[:], nonceBytes)
	for _, board := range []uint32{0x54474732, 0x484c5633, 0x51524c50} {
		for _, relay := range []string{"", "F4MLV-10"} {
			t.Run(fmt.Sprintf("%x/%s", board, relay), func(t *testing.T) {
				p := newFakeOTA(board)
				p.image = image
				p.relay = relay
				p.firstNonce = &nonce
				p.routeKey, _ = hex.DecodeString(f.RouteKey)
				var out bytes.Buffer
				if err := runNative(nativeArgs(t, p), &out, func(string) (otaPort, error) { return p, nil }, p.clock); err != nil {
					t.Fatal(err)
				}
				expected := map[string]string{}
				for _, v := range f.Frames {
					if v.Op == 15 && !strings.HasSuffix(v.Name, fmt.Sprintf("%08X", board)) {
						continue
					}
					raw := v.Wire
					if relay != "" {
						raw = v.Routed
					}
					expected[fmt.Sprintf("%d/%d", v.Op, v.Offset)] = raw
				}
				compared := 0
				for _, wire := range p.txFrames {
					inner := wire
					if relay != "" {
						inner = wire[13 : len(wire)-16]
					}
					op := inner[4]
					offset := binary.BigEndian.Uint32(inner[13:17])
					if op == 6 {
						continue
					}
					want, ok := expected[fmt.Sprintf("%d/%d", op, offset)]
					if !ok {
						t.Fatal("missing reference", op, offset)
					}
					if hex.EncodeToString(wire) != want {
						t.Fatalf("actual engine frame mismatch: op=%d offset=%d\ngot %x\nwant %s", op, offset, wire, want)
					}
					compared++
					if op == 19 {
						break
					}
				}
				if compared < 10 {
					t.Fatal("insufficient emitted frames compared", compared)
				}
			})
		}
	}
}

func TestNativeHelloCounterMatchesReference(t *testing.T) {
	var f struct {
		Frames   []struct{ Name, Wire, Routed string }
		RouteKey string `json:"route_key"`
	}
	b, err := os.ReadFile("testdata/reference-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	for _, relay := range []string{"", "F4MLV-10"} {
		p := newFakeOTA(0x54474732)
		p.clock.at = time.Unix(71, 0)
		p.relay = relay
		p.routeKey, _ = hex.DecodeString(f.RouteKey)
		e := &nativeEngine{bridge: &bridge{port: p, clock: p.clock}, clock: p.clock, key: p.key, routeKey: p.routeKey, source: p.source, target: p.target, relay: relay, counterFile: filepath.Join(t.TempDir(), "counter"), normalTimeout: time.Second, event: func(string, map[string]any) {}}
		if _, err = e.hello(1); err != nil {
			t.Fatal(err)
		}
		for _, v := range f.Frames {
			if v.Name == "hello-counter-71" {
				want := v.Wire
				if relay != "" {
					want = v.Routed
				}
				if len(p.txFrames) != 1 || hex.EncodeToString(p.txFrames[0]) != want {
					t.Fatal("HELLO bytes differ from reference")
				}
			}
		}
	}
}
